INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, choose_if, faq, rating, also_consider, published, last_updated) VALUES ($t$granola$t$, $t$en$t$, $t$Granola$t$, $t$https://www.granola.ai$t$, $t$granola.ai$t$, $t$productivity$t$, $t$freemium$t$, $t$Free / from $14/mo$t$, $t$Bot-free AI meeting notes, pre-meeting briefs, chat across meetings, MCP for AI tools$t$, $t$Granola is an AI notepad that transcribes meetings from your device's audio without a bot joining the call, then combines your rough notes and the transcript into structured notes, action items and follow-ups. It runs on Mac, Windows, iPhone, Android and Apple Watch.$t$, $t$Granola is an AI notepad for people in back-to-back meetings. Instead of sending a bot into the call, it captures audio from your own device, so it works with Zoom, Google Meet, Microsoft Teams, Slack huddles and in-person conversations. You can type rough notes during the meeting, and Granola combines them with the transcript to produce structured notes, action items and follow-ups.

Granola shipped a steady run of updates in 2026: the Granola MCP connector in February, which brings meeting notes into Claude, ChatGPT, Cursor and other AI tools; a $125 million funding round in March, announced together with Spaces with team chat, personal and enterprise APIs and enterprise controls; a rebuilt agentic Chat with inline citations and Recipes in April; Briefs that prepare you for the next meeting in May; an Android app in July; an Apple Watch app on July 28; and support for 32 languages in September.

Beyond notes, Granola offers AI chat within a meeting and across all your meetings, custom note templates, shared folders, pre-meeting briefs on attendees and earlier discussions, and one-click follow-up emails. Paid plans connect to Attio, Notion, HubSpot, Affinity and Zapier, and Enterprise adds Salesforce. MCP and API access let other apps and agents use your meeting history.

Pricing is per user per month. Basic is free and includes AI meeting notes, chat, shared folders, templates and multi-language support, but only shows the last 30 days of meeting history and uses automatic model selection. Business costs $14 per user per month and adds unlimited history, pre-meeting briefs, follow-up emails, model choice including advanced thinking models, integrations, MCP and API access, and centralized billing. Enterprise costs $35 per user per month and adds SSO, SCIM, workspace policies for retention and sharing, HIPAA-compliant workspaces, usage analytics, an audit API and admin controls for MCP and API. Granola's pricing page does not say whether these rates are for monthly or annual billing.

The free plan's 30-day history makes it more of a trial for regular users. Because there is no bot, other participants do not see a notetaker join, so getting consent is up to you; an organization-wide notification that Granola is in use is still a pilot feature on Enterprise. SSO and admin controls require Enterprise, and as with any transcription tool, results depend on audio quality.

Granola suits founders, managers, investors and sales or customer teams who sit in many meetings, dislike meeting bots and want to keep taking their own notes with AI filling in the gaps. Teams that want a bot-based recorder with video replay may prefer Otter.ai or Fireflies.ai.$t$, ARRAY[$t$No bot joins the call: captures audio from your device across Zoom, Meet, Teams, huddles and in-person meetings$t$, $t$Builds on your own rough notes instead of replacing them with a generic summary$t$, $t$Apps for Mac, Windows, iPhone, Android and Apple Watch$t$, $t$MCP connector and API bring meeting notes into Claude, ChatGPT and Cursor$t$, $t$Supports 32 languages since September 2026$t$]::text[], ARRAY[$t$Free Basic plan only shows the last 30 days of meeting history$t$, $t$Pre-meeting briefs, follow-up emails, integrations and API need the $14 Business plan$t$, $t$SSO, SCIM and admin controls only on the $35 Enterprise plan$t$, $t$With no bot, other participants are not automatically told they are being transcribed; the org-wide notice is still a pilot$t$]::text[], $t$["✅ You dislike meeting bots and want notes captured quietly from your own device", "✅ You like to take your own notes and want AI to fill in the gaps", "✅ You want your meeting history available in Claude, ChatGPT or Cursor through MCP", "✅ Your team wants shared folders and chat across everyone's meetings"]$t$::jsonb, $t$[{"q": "What is Granola?", "a": "Granola is an AI notepad for meetings. It transcribes audio from your computer or phone without a bot joining the call and turns your rough notes plus the transcript into structured notes, action items and follow-ups. It works with Zoom, Google Meet, Teams, Slack huddles and in-person meetings."}, {"q": "Is Granola free?", "a": "Yes, the Basic plan is free and includes AI meeting notes, chat, shared folders and templates, but you can only see the last 30 days of meeting history. Business costs $14 per user per month for unlimited history, briefs, follow-up emails, integrations, MCP and API access. Enterprise costs $35 per user per month."}, {"q": "Does Granola use a meeting bot?", "a": "No. Granola records audio from your own device, so no bot appears in the call. That also means other participants are not automatically notified, so you should tell them you are taking AI notes. An organization-wide notification is available as a pilot on Enterprise."}, {"q": "Which platforms does Granola support?", "a": "Granola has apps for macOS, Windows, iOS and Android, plus an Apple Watch app launched in July 2026. It also connects to AI tools such as Claude, ChatGPT and Cursor through its MCP connector."}]$t$::jsonb, NULL, ARRAY[$t$otter-ai$t$, $t$fireflies-ai$t$, $t$notion-ai$t$]::text[], false, $t$2026-10-25$t$::date)
ON CONFLICT (slug, lang) DO NOTHING;
