INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, choose_if, faq, rating, also_consider, published, last_updated) VALUES ($t$base44$t$, $t$en$t$, $t$Base44$t$, $t$https://base44.com$t$, $t$base44.com$t$, $t$nocode$t$, $t$freemium$t$, $t$Free / from $16/mo$t$, $t$Building full-stack apps, websites and AI agents from a prompt, with backend and hosting built in$t$, $t$Base44 is Wix's AI app builder that creates full-stack web apps, websites and AI agents from plain-language prompts, with database, authentication, payments and hosting built in. The free plan includes 25 message credits a month, and paid plans start at $16 a month billed annually.$t$, $t$Base44 is an AI platform for building apps, websites and AI agents by describing them in plain language, with no coding required. It generates the frontend and backend together, including the database, user authentication, payments and hosting, so apps run on production infrastructure rather than in a sandbox. It connects to tools such as Gmail, Slack, Notion, Google Drive, HubSpot and Salesforce, and to external services through APIs.

Base44 was founded by Maor Shlomo, came out of stealth in March 2025 and was acquired by Wix in June 2025; it continues to run as its own product. In June 2026 Base44 launched Base 1, its own language model, which the company says is already serving users on the platform. Wix has said Base44 reached about $100 million in annual recurring revenue within a year of its founding.

Beyond apps, Base44 builds websites with AI-generated design, custom domains and SEO and GEO tools, and Superagents that automate workflows across your connected tools. Every plan includes a responsive visual editor, analytics dashboard, cloud storage, marketing tools, debugging tools and multi-user editing. Paid plans add in-app code edits, and higher tiers add model selection, GitHub integration and early access to beta features. Developers can also use an SDK, CLI and MCP server.

Pricing uses message credits for AI building and integration credits for actions your app performs. Free costs $0 with 25 message credits and 100 integration credits a month and up to 5 apps. Starter is $20 a month billed monthly or $16 billed annually, with 100 message and 2,000 integration credits and unlimited apps. Builder is $50 or $40, with 250 and 10,000 credits plus model selection and GitHub integration. Pro is $100 or $80, with 500 and 20,000 credits and early beta access. Elite is $200 or $160, with 1,200 and 50,000 credits and premium support. Enterprise is custom, with SSO and advanced security controls. Annual billing saves 20%.

Message credits go quickly: 25 a month on the free plan and 100 on Starter leave little room for iteration on a larger app. Apps run on Base44's own backend and hosting, which simplifies launch but ties you to the platform, and GitHub integration starts only on the Builder plan. Complex apps still require you to understand the logic well enough to debug what the AI builds. Base44 states that you own everything you build.

Base44 suits founders, small businesses and non-developers who want a working app with login, data and payments without setting up a backend, and teams building internal tools fast. Developers who want more control over the code may prefer Lovable, Bolt.new or Replit.$t$, ARRAY[$t$Builds full-stack apps from a prompt, with database, authentication, payments and hosting included$t$, $t$Integrations with Gmail, Slack, Notion, Google Drive, HubSpot and Salesforce$t$, $t$Free plan with up to 5 apps, and every plan includes multi-user editing$t$, $t$Superagents and in-app AI agents for automating workflows$t$, $t$Backed by Wix, with its own Base 1 model in production since June 2026$t$]::text[], ARRAY[$t$Only 25 message credits a month on Free and 100 on Starter, which limits iteration$t$, $t$Apps run on Base44's backend and hosting, creating platform lock-in$t$, $t$GitHub integration and model selection start on the $40-a-month Builder plan$t$, $t$Complex apps still require debugging skills to fix what the AI generates$t$]::text[], $t$["✅ You want a working app with login, database and payments without setting up a backend", "✅ You are a founder or small business validating an idea quickly", "✅ You need internal tools connected to Gmail, Slack, Notion or your CRM", "✅ You prefer an all-in-one platform over managing hosting yourself"]$t$::jsonb, $t$[{"q": "What is Base44?", "a": "Base44 is an AI app builder owned by Wix. You describe the app, website or AI agent you want in plain language, and Base44 builds the frontend, backend, database, authentication and hosting so it can go live right away."}, {"q": "Is Base44 free?", "a": "Yes. The Free plan includes 25 message credits and 100 integration credits a month and up to 5 apps. Paid plans start with Starter at $16 a month billed annually or $20 billed monthly, and go up to Elite at $160 a month billed annually or $200 monthly."}, {"q": "Who owns Base44?", "a": "Wix acquired Base44 in June 2025. Base44 continues to operate as its own product, and in June 2026 it launched Base 1, its own AI model."}, {"q": "Do I own the apps I build on Base44?", "a": "Base44 states that you own everything you build on the platform. Apps run on Base44's built-in backend and hosting, and GitHub integration is available from the Builder plan."}]$t$::jsonb, NULL, ARRAY[$t$lovable$t$, $t$bolt-new$t$, $t$replit$t$]::text[], false, $t$2026-10-25$t$::date)
ON CONFLICT (slug, lang) DO NOTHING;
