INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, choose_if, faq, rating, also_consider, published, last_updated) VALUES ($t$base44$t$, $t$pt$t$, $t$Base44$t$, $t$https://base44.com$t$, $t$base44.com$t$, $t$nocode$t$, $t$freemium$t$, $t$Free / from $16/mo$t$, $t$Building full-stack apps, websites and AI agents from a prompt, with backend and hosting built in$t$, $t$Base44 is Wix's AI app builder that creates full-stack web apps, websites and AI agents from plain-language prompts, with database, authentication, payments and hosting built in. The free plan includes 25 message credits a month, and paid plans start at $16 a month billed annually.$t$, $t$Base44 is an AI platform for building apps, websites and AI agents by describing them in plain language, with no coding required. It generates the frontend and backend together, including the database, user authentication, payments and hosting, so apps run on production infrastructure rather than in a sandbox. It connects to tools such as Gmail, Slack, Notion, Google Drive, HubSpot and Salesforce, and to external services through APIs.

Base44 was founded by Maor Shlomo, came out of stealth in March 2025 and was acquired by Wix in June 2025; it continues to run as its own product. In June 2026 Base44 launched Base 1, its own language model, which the company says is already serving users on the platform. Wix has said Base44 reached about $100 million in annual recurring revenue within a year of its founding.

Beyond apps, Base44 builds websites with AI-generated design, custom domains and SEO and GEO tools, and Superagents that automate workflows across your connected tools. Every plan includes a responsive visual editor, analytics dashboard, cloud storage, marketing tools, debugging tools and multi-user editing. Paid plans add in-app code edits, and higher tiers add model selection, GitHub integration and early access to beta features. Developers can also use an SDK, CLI and MCP server.

Pricing uses message credits for AI building and integration credits for actions your app performs. Free costs $0 with 25 message credits and 100 integration credits a month and up to 5 apps. Starter is $20 a month billed monthly or $16 billed annually, with 100 message and 2,000 integration credits and unlimited apps. Builder is $50 or $40, with 250 and 10,000 credits plus model selection and GitHub integration. Pro is $100 or $80, with 500 and 20,000 credits and early beta access. Elite is $200 or $160, with 1,200 and 50,000 credits and premium support. Enterprise is custom, with SSO and advanced security controls. Annual billing saves 20%.

Message credits go quickly: 25 a month on the free plan and 100 on Starter leave little room for iteration on a larger app. Apps run on Base44's own backend and hosting, which simplifies launch but ties you to the platform, and GitHub integration starts only on the Builder plan. Complex apps still require you to understand the logic well enough to debug what the AI builds. Base44 states that you own everything you build.

Base44 suits founders, small businesses and non-developers who want a working app with login, data and payments without setting up a backend, and teams building internal tools fast. Developers who want more control over the code may prefer Lovable, Bolt.new or Replit.$t$, ARRAY[$t$Builds full-stack apps from a prompt, with database, authentication, payments and hosting included$t$, $t$Integrations with Gmail, Slack, Notion, Google Drive, HubSpot and Salesforce$t$, $t$Free plan with up to 5 apps, and every plan includes multi-user editing$t$, $t$Superagents and in-app AI agents for automating workflows$t$, $t$Backed by Wix, with its own Base 1 model in production since June 2026$t$]::text[], ARRAY[$t$Only 25 message credits a month on Free and 100 on Starter, which limits iteration$t$, $t$Apps run on Base44's backend and hosting, creating platform lock-in$t$, $t$GitHub integration and model selection start on the $40-a-month Builder plan$t$, $t$Complex apps still require debugging skills to fix what the AI generates$t$]::text[], $t$["✅ You want a working app with login, database and payments without setting up a backend", "✅ You are a founder or small business validating an idea quickly", "✅ You need internal tools connected to Gmail, Slack, Notion or your CRM", "✅ You prefer an all-in-one platform over managing hosting yourself"]$t$::jsonb, $t$[{"q": "What is Base44?", "a": "Base44 is an AI app builder owned by Wix. You describe the app, website or AI agent you want in plain language, and Base44 builds the frontend, backend, database, authentication and hosting so it can go live right away."}, {"q": "Is Base44 free?", "a": "Yes. The Free plan includes 25 message credits and 100 integration credits a month and up to 5 apps. Paid plans start with Starter at $16 a month billed annually or $20 billed monthly, and go up to Elite at $160 a month billed annually or $200 monthly."}, {"q": "Who owns Base44?", "a": "Wix acquired Base44 in June 2025. Base44 continues to operate as its own product, and in June 2026 it launched Base 1, its own AI model."}, {"q": "Do I own the apps I build on Base44?", "a": "Base44 states that you own everything you build on the platform. Apps run on Base44's built-in backend and hosting, and GitHub integration is available from the Builder plan."}]$t$::jsonb, NULL, ARRAY[$t$lovable$t$, $t$bolt-new$t$, $t$replit$t$]::text[], false, $t$2026-10-25$t$::date)
ON CONFLICT (slug, lang) DO NOTHING;
INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, choose_if, faq, rating, also_consider, published, last_updated) VALUES ($t$freepik$t$, $t$en$t$, $t$Magnific (formerly Freepik)$t$, $t$https://www.magnific.com$t$, $t$magnific.com$t$, $t$image$t$, $t$freemium$t$, $t$1M+$t$, $t$AI image, video and audio generation across 30+ models, plus 250M+ stock assets$t$, $t$Magnific, the name Freepik has used since April 2026, is an AI creative platform that combines image, video and audio generation across 30+ models with a library of more than 250 million stock assets. A free account allows a limited number of AI generations per day, while paid plans add credits, unlimited generation on selected models and a commercial license.$t$, $t$Freepik started in Málaga in 2010 as a search engine for free graphic resources and grew into one of the largest stock libraries for photos, vectors, icons and templates. On April 28, 2026 it rebranded as Magnific, the name of the AI upscaling startup it acquired in May 2024, to bring its stock library, generative AI tools and upscalers under one brand. freepik.com now redirects to magnific.com.

Magnific says it has more than 1 million subscribers. Rather than relying only on its own models, it gives subscribers access to leading third-party models, including Kling 4.0 and 3.0, Seedance 2.5, Google Veo 3.1, Gemini Omni, MiniMax, Nano Banana 2 and Nano Banana Pro, FLUX.2, Recraft and Ideogram for images and video, plus Google Lyria 3 and ElevenLabs for music. In October 2026 it added Magnific One, its own image model, together with a Brand Kit feature.

Beyond generation, Magnific includes Spaces, a shared canvas for building workflows, pro editing tools for image, video and design, the Magnific image and video upscalers, music, voice and sound effect generation, custom AI characters on paid plans, an MCP server and plugins, a ComfyUI integration, API access and metadata export. The stock library of more than 250 million photos, videos, vectors and PSDs is part of the same subscription.

The Free plan has no credits but allows daily use of basic AI tools, including up to 20 image generations a day, plus 10 stock downloads a day, for personal use with attribution. Premium includes 20,000 credits a month (240,000 a year on annual billing), all premium stock, 100 downloads a day and a commercial license. Premium+ includes 45,000 credits a month (600,000 a year), unlimited generation on most image models and the option to buy extra credits. Pro comes in two tiers with 112,500 or 300,000 credits a month and adds a merchandise license and early access. Business covers teams of up to 100 seats, and Enterprise is custom. Prices are shown in local currency and vary by region, annual billing is much cheaper than monthly, promotions are frequent, and there is a 30-day refund guarantee.

There is no single published price list in US dollars, so check the pricing page for your region before subscribing. Credit costs vary widely: a Nano Banana 2 image at 2K uses 75 credits, while 4 seconds of Seedance 2.5 video at 1080p uses 4,400. Unlimited generation covers most image models, but video, audio and editing tools still use credits. Free use is personal only and requires attribution, and the rebrand means older Freepik links and guides now point to Magnific.

Magnific suits designers, marketers and agencies who want stock content and many AI models in one subscription, especially for high volumes of images. If you only need one image model, Midjourney, Leonardo AI or Krea AI may be simpler, and Adobe Firefly fits teams already using Adobe Creative Cloud.$t$, ARRAY[$t$30+ image, video and audio models plus 250M+ stock assets in one subscription$t$, $t$Unlimited generation on most image models from Premium+$t$, $t$Built-in Magnific upscalers, Spaces workflows, MCP, ComfyUI and API access$t$, $t$Free plan with up to 20 AI image generations and 10 stock downloads a day$t$, $t$Commercial license on all paid plans, with a merchandise license on Pro$t$]::text[], ARRAY[$t$No single published USD price list; prices vary by region and promotions change often$t$, $t$Video, audio and editing tools always use credits, and video is credit-intensive$t$, $t$Free use is personal only and requires attribution$t$, $t$Extra credits cannot be bought on Premium, only on Premium+ and above$t$, $t$The April 2026 rebrand from Freepik to Magnific can confuse existing users$t$]::text[], $t$["✅ You need both stock assets and AI generation from one subscription", "✅ You generate many images and want unlimited use of models like Nano Banana", "✅ You want to try many video models, such as Kling, Seedance and Veo, in one place", "✅ You need built-in upscaling for print or high-resolution work"]$t$::jsonb, $t$[{"q": "Is Freepik now called Magnific?", "a": "Yes. On April 28, 2026 Freepik rebranded as Magnific, uniting its stock library, AI generation tools and the Magnific upscaler under one name. freepik.com now redirects to magnific.com."}, {"q": "Is Magnific (Freepik) free?", "a": "There is a free plan with no credits but daily limits, such as up to 20 AI image generations and 10 stock downloads per day, for personal use with attribution. Paid plans (Premium, Premium+, Pro, Business) add monthly credits, premium stock and a commercial license; prices are shown in local currency and vary by region."}, {"q": "Which AI models does Magnific include?", "a": "Magnific offers 30+ models, including Kling, Seedance, Google Veo, Nano Banana 2 and Nano Banana Pro, FLUX.2, Recraft and Ideogram, plus its own Magnific One image model and music models such as Google Lyria 3 and ElevenLabs."}, {"q": "What does unlimited mean on Magnific?", "a": "Premium+ and Pro include unlimited generation on most image models and some video models. Some premium models and all video, audio and editing tools still consume credits, and speed can be limited during busy periods."}]$t$::jsonb, NULL, ARRAY[$t$krea-ai$t$, $t$adobe-firefly$t$, $t$leonardo-ai$t$]::text[], false, $t$2026-10-25$t$::date)
ON CONFLICT (slug, lang) DO NOTHING;
